/bin/bash -lc "python3 - <<'PY'
# Local sensitivity check only: compare standard chromosome choices and CDS stop handling.
import gzip, math
from collections import defaultdict, Counter
import numpy as np
path='inputs/MANE.GRCh38.v1.3.refseq_genomic.gtf.gz'

def parse_attrs(f):
    d=defaultdict(list)
    for item in f.rstrip(';').split(';'):
        item=item.strip()
        if item:
            k,v=item.split(' ',1); d[k].append(v.strip().strip('\"'))
    return d

def union(xs):
    m=[]
    for s,e in sorted(xs):
        if not m or s>m[-1][1]+1: m.append([s,e])
        elif e>m[-1][1]: m[-1][1]=e
    return sum(e-s+1 for s,e in m)

def clip(exons, low=None, high=None):
    total=0
    for s,e in exons:
        if low is not None: s=max(s,low)
        if high is not None: e=min(e,high)
        if s<=e: total+=e-s+1
    return total
rows=[]; seqc=Counter(); feats=Counter(); tags=Counter()
with gzip.open(path,'rt') as fh:
    for line in fh:
        if line.startswith('#'): continue
        p=line.rstrip('\\n').split('\\t')
        if len(p)"'!=9: continue
        seq,_,feat,s,e,_,strand,_,af=p; a=parse_attrs(af)
        if feat=='"'transcript':
            for t in a.get('tag',[]): tags[t]+=1
        seqc[seq]+=1; feats[feat]+=1
        rows.append((seq,feat,int(s),int(e),strand,a))
print('features', feats)
print('transcript tags', tags)
print('seq standard-ish count top/bottom', len(seqc), seqc.most_common(30))
for include_m in [True,False]:
    std={f'chr{i}' for i in range(1,23)}|{'chrX','chrY'}|({'chrM'} if include_m else set())
    for stop in [True,False]:
        selected={}; ex=defaultdict(list); cd=defaultdict(list)
        for seq,feat,s,e,strand,a in rows:
            if seq not in std: continue
            tid=a.get('transcript_id',[''])[0]
            if feat=='transcript' and 'MANE Select' in set(a.get('tag',[])): selected[tid]=strand
            if tid and feat=='exon': ex[tid].append((s,e))
            if tid and (feat=='CDS' or (stop and feat=='stop_codon')): cd[tid].append((s,e))
        vals=[[],[],[]]
        for tid,strand in selected.items():
            cs=min(s for s,e in cd[tid]); ce=max(e for s,e in cd[tid])
            vals[1].append(union(cd[tid]))
            if strand=='+': vals[0].append(clip(ex[tid],high=cs-1)); vals[2].append(clip(ex[tid],low=ce+1))
            else: vals[0].append(clip(ex[tid],low=ce+1)); vals[2].append(clip(ex[tid],high=cs-1))
        print('include_m',include_m,'stop',stop,'n',len(vals[0]),'med', [math.floor(np.median(v)) for v in vals])
PY"
